def pytest_collection_modifyitems(config: pytest.Config, items: list[pytest.Item]) -> None:
    """Skip only explicitly annotated Windows page-authority premises off Windows."""

    del config
    for item in items:
        path = str(item.fspath).replace("\\", "/")
        relative = path[path.index("tests/") :] if "tests/" in path else path
        if item.originalname in _WINDOWS_PAGE_AUTHORITY_BASE_TESTS.get(relative, set()):
            item.add_marker(pytest.mark.requires_windows_page_authority)
            if sys.platform != "win32":
                item.add_marker(pytest.mark.skip(reason="requires canonical Windows page authority"))
